sys_script_include.script:
var IAWUtils = Class.create();
IAWUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /*

	The Script include receives JSON Obj input from the below Business Rules

	IAW Manual Allocation Level Handler
	IAW Fund Code Update Handler
	IAW Block Trade Mismatch Handler
	IAW Fund Code Identifier Handler
	IAW Allocation Level Mismatch Handler

	The Request type is selected based on thw below switch case and accessed the relevant method in Script inlcude in x_hsb11_iaw_widget.IAWPayloadFormatter()
	which will provide parameters to create record in IAW Outbounds to populate the below mapped fields

    This script include is created as part of MSSOTIQUBE - 511 which will be extended for the usage
    MSSOTIQUBE - 195 , MSSOTIQUBE - 196, MSSOTIQUBE - 197, MSSOTIQUBE - 198 , MSSOTIQUBE - 199
	Review as per MSSOTIQUBE-1097
    */

    processPayload: function(requestBody) {


        var gRecord = new GlideRecord('x_hsb11_iaw_widget_iaw_outbound');
        gRecord.initialize();
        gRecord.sn_task = requestBody.sn_task;
        gRecord.state = "1";
        gRecord.request_type = requestBody.request_type;

        try {
            var stringifyPayload = requestBody.payload; //modified as per 184 //passing the direct JSON Object from the business rule and fetching the payload parameter
        } catch (err) {
            gs.error("IAWUtils: Invalid JSON, IAW API not called. Error message" + err.message);
            gRecord.state = "4";
            gRecord.response_body = "Invalid JSON, IAW API not called. Error message" + err.message;
        }

        var iawFormatter = new x_hsb11_iaw_widget.IAWPayloadFormatter();

        switch (requestBody.request_type) { //184 - passing the direct JSON Object from the business rule and fetching the Request type parameter
            case "CUH":
                var cuh_payload = iawFormatter.format_cuh(stringifyPayload);
                gRecord.ctac_trade_id = cuh_payload.ctac_trade_id;
                gRecord.ctac_allocation_id = cuh_payload.ctac_allocation_id;
                gRecord.counterparty_code = cuh_payload.counterparty_code;
                gRecord.subaccount_view = cuh_payload.subaccount_view;
                break;
            case "FCIH":
                var fcih_payload = iawFormatter.format_fcih(stringifyPayload);
                gRecord.ctac_trade_id = fcih_payload.ctac_trade_id;
                gRecord.counterparty_code = fcih_payload.counterparty_code;
                gRecord.ctac_trans_msg_p1 = fcih_payload.ctac_trans_msg_p1;
                gRecord.counterparty_account = JSON.stringify(fcih_payload.counterparty_account);
                break;
            case "ALMH":
                var almh_payload = iawFormatter.format_almh(stringifyPayload);
                gRecord.ctac_trade_id = almh_payload.ctac_trade_id;
                gRecord.counterparty_code = almh_payload.counterparty_code;
                gRecord.ctac_allocation_id = almh_payload.ctac_allocation_id;
                gRecord.trading_entity_id = almh_payload.trading_entity_id;
                gRecord.buy_sell = almh_payload.buy_sell;
                gRecord.exchange_id = almh_payload.exchange_id;
                gRecord.ctac_ctm_trade_detail_fld_comp = JSON.stringify(almh_payload.ctac_ctm_trade_detail_fld_comp);
                break;
            case "BTMH":
                var btmh_payload = iawFormatter.format_btmh(stringifyPayload);
                gRecord.ctac_trade_id = btmh_payload.ctac_trade_id;
                gRecord.counterparty_code = btmh_payload.counterparty_code;
                gRecord.trading_entity_id = btmh_payload.trading_entity_id;
                gRecord.buy_sell = btmh_payload.buy_sell;
                gRecord.exchange_id = btmh_payload.exchange_id;
                gRecord.ctac_ctm_trade_level_fld_comp = JSON.stringify(btmh_payload.ctac_ctm_trade_level_fld_comp);
                break;
            case "MAIH":
                var maih_payload = iawFormatter.format_maih(stringifyPayload, requestBody.allocation_details); //184 -passing the direct JSON Object from the business rule and fetching the Allocation details JSOn Object
                gRecord.block_trade_details = JSON.stringify(maih_payload.block_trade_details);
                gRecord.client_allocation_details = JSON.stringify(maih_payload.client_allocation_details);
                break;
        }
        gRecord.insert();

    },

    type: 'IAWUtils'
});
